import{_ as t,o,c as a,a2 as n}from"./chunks/framework.CpZKh-tG.js";const u=JSON.parse('{"title":"PWA stuck-on-old-version — root cause + fix (2026-07-01)","description":"","frontmatter":{},"headers":[],"relativePath":"wip/pwa-precache-i18n-bundling.md","filePath":"wip/pwa-precache-i18n-bundling.md"}'),s={name:"wip/pwa-precache-i18n-bundling.md"};function i(r,e,d,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="pwa-stuck-on-old-version-—-root-cause-fix-2026-07-01" tabindex="-1">PWA stuck-on-old-version — root cause + fix (2026-07-01) <a class="header-anchor" href="#pwa-stuck-on-old-version-—-root-cause-fix-2026-07-01" aria-label="Permalink to &quot;PWA stuck-on-old-version — root cause + fix (2026-07-01)&quot;">​</a></h1><p><strong>Status:</strong> implemented, harness-green locally, not yet deployed. No push without approval.</p><p>Supersedes the diagnosis half of <code>pwa-upgrade-path-handover.md</code>.</p><h2 id="symptom" tabindex="-1">Symptom <a class="header-anchor" href="#symptom" aria-label="Permalink to &quot;Symptom&quot;">​</a></h2><p>Installed PWA clients on mobile (iPhone Safari, and Firefox-iOS which is also WebKit) were stranded on <strong>v0.6.3</strong> and never rolled forward to v0.7. Closing/reopening the tab didn&#39;t help. A <strong>private tab loaded v0.7 fine</strong>.</p><h2 id="root-cause-evidence-backed-not-assumed" tabindex="-1">Root cause (evidence-backed, not assumed) <a class="header-anchor" href="#root-cause-evidence-backed-not-assumed" aria-label="Permalink to &quot;Root cause (evidence-backed, not assumed)&quot;">​</a></h2><p>A private tab runs <strong>no service worker</strong> — it just fetches from the network, so &quot;private works&quot; proved only that the site serves v0.7, <em>not</em> that the SW installs. Every real attempt to install the v0.7 SW happened behind the old 0.6.3 SW, and that install <strong>never completed</strong>.</p><p>On-device diagnosis (read-only console snippet on the stuck tab) showed:</p><ul><li>controller = <code>0.6.3 sw.js [activated]</code> (old SW still in charge)</li><li>a v0.7 SW stuck in state <strong><code>installing</code></strong> (never <code>installed</code>/<code>activated</code>)</li><li>storage usage <strong>357 MB / 39 GB (0.9%)</strong> → <strong>not</strong> a quota problem</li><li>a probe of all <strong>4,456</strong> precache URLs from the deployed sw.js: every one returned 200, no redirects/404s/timeouts → <strong>not</strong> a bad resource</li></ul><p>By elimination + the <code>installing</code>-stuck state: the SW <strong>precache install of 4,456 entries never finishes on mobile WebKit</strong>. Until it does, <code>skipWaiting</code>/ <code>clientsClaim</code> never fire, so the old 0.6.3 SW keeps controlling the page. It is a <strong>file-count</strong> problem, not bytes and not a specific file.</p><p>Where the 4,456 came from (deployed inventory): ~2,019 per-locale prerendered pages + ~1,816 tiny i18n JSON files + 282 images + shell. The site ships <strong>10,360</strong> individual i18n overlay files (<code>static/data/i18n/{locale}/**</code>, 740 topics × 14 locales, ~1.3 KB each) — a pathological count. Images (6,029 files / 1.7 GB) and audio were already runtime-cached and were never the issue.</p><h2 id="fix" tabindex="-1">Fix <a class="header-anchor" href="#fix" aria-label="Permalink to &quot;Fix&quot;">​</a></h2><p>Shrink the SW install to a small, bounded shell that always completes, and serve everything else at runtime — without losing offline coverage.</p><ol><li><p><strong>Bundle the i18n overlays</strong> (<code>scripts/build-i18n-bundles.mjs</code>, wired into <code>npm run build</code> before <code>vite build</code>). Reads each locale&#39;s ~740 topic files and emits one <code>static/data/i18n/{locale}.json</code> = <code>{ &quot;&lt;relpath&gt;&quot;: content }</code>. <strong>10,360 files → 14 bundles.</strong> Source per-file tree is left untouched (translator scripts, <code>$data</code> static imports, and the filesystem drift tests keep working). Bundles are git-ignored (generated).</p></li><li><p><strong>Loader reads bundles</strong> (<code>src/lib/data.ts</code> <code>get()</code>): intercepts <code>i18n/{locale}/{key}</code>, fetches the per-locale bundle once (cached promise), indexes by key, throws on a genuine miss so the en-US fallback still fires. Falls back to the legacy per-file fetch if a bundle is absent (e.g. <code>vite dev</code> before a build) — so dev without a build still works.</p></li><li><p><strong>Shell-only precache</strong> (<code>vite.config.ts</code> workbox): <code>globPatterns: [&#39;client/**/*.{js,css,woff2,svg,ico}&#39;, &#39;client/data/i18n/*.json&#39;, &#39;prerendered/pages/index.html&#39;]</code>. Prefixing with both <code>client/</code> and <code>prerendered/</code> disables <code>@vite-pwa/sveltekit</code>&#39;s <code>buildGlobPatterns</code> force-add (which otherwise pulls all pages + JSON + imagery back in). <code>navigateFallback</code> → the precached home page (base-aware <code>/</code> or <code>/orrery/</code>); pages render client-side from the shell. Data JSON, imagery, audio load at runtime via the existing + added <code>runtimeCaching</code> rules.</p></li></ol><p><strong>Result: 355 precache entries (was 4,456)</strong> — 340 shell + 14 all-language i18n bundles + 1 SPA home shell. ~19 MB, comprehensive offline in every language. Individual-language pages/data/images stream on demand.</p><h2 id="verification-local-harness-—-tmp-pwa-harness-harness-mjs" tabindex="-1">Verification (local harness — <code>/tmp/pwa-harness/harness.mjs</code>) <a class="header-anchor" href="#verification-local-harness-—-tmp-pwa-harness-harness-mjs" aria-label="Permalink to &quot;Verification (local harness — `/tmp/pwa-harness/harness.mjs`)&quot;">​</a></h2><p>Serves an old build, installs its SW, &quot;deploys&quot; the new build at the same origin, reload-loops, reports UPGRADED/STUCK. Also a FRESH mode (from-empty install must reach <code>activated</code>). Run in Chromium <strong>and</strong> WebKit (Safari&#39;s engine):</p><table tabindex="0"><thead><tr><th>Check</th><th>Chromium</th><th>WebKit</th></tr></thead><tbody><tr><td>0.6.3 → 0.7 upgrade</td><td>UPGRADED (1 reload)</td><td>UPGRADED</td></tr><tr><td>Fresh 0.7 install</td><td>activated, v0.7</td><td>activated, v0.7</td></tr></tbody></table><p><strong>Caveat:</strong> desktop (even desktop WebKit) has far more headroom than an iPhone and does <strong>not</strong> reproduce the install hang — it powered through 4,456 too. So the harness proves the design is sound and non-regressive; the true mobile confirmation is <strong>post-deploy on the phone</strong> (open site, run the <code>Diag</code> bookmark, confirm the new SW reaches <code>activated</code>). The count drop (4,456 → 355, and the 10,360 → 14 bundle collapse) is the mobile-fix evidence.</p><h2 id="follow-ups-not-required-to-unstick" tabindex="-1">Follow-ups (not required to unstick) <a class="header-anchor" href="#follow-ups-not-required-to-unstick" aria-label="Permalink to &quot;Follow-ups (not required to unstick)&quot;">​</a></h2><ul><li><strong>Prune</strong> the now-unused individual <code>build/data/i18n/{locale}/**</code> files from the deploy (dead weight, ~24 MB; nothing fetches them at runtime — the <code>$data</code> static imports are compile-time). Optional deploy-size win.</li><li><strong>Tier-3 prefetch:</strong> on language change, background-fetch that locale&#39;s bundle so first offline use in a new language is instant. Small enhancement.</li><li>Consider promoting the harness into <code>scripts/</code> as a CI deploy gate.</li></ul><h2 id="files-changed" tabindex="-1">Files changed <a class="header-anchor" href="#files-changed" aria-label="Permalink to &quot;Files changed&quot;">​</a></h2><ul><li><code>scripts/build-i18n-bundles.mjs</code> (new)</li><li><code>package.json</code> (build chain + <code>build-i18n-bundles</code> script)</li><li><code>src/lib/data.ts</code> (bundle loader + <code>__resetCache</code>)</li><li><code>vite.config.ts</code> (globPatterns + navigateFallback)</li><li><code>.gitignore</code> (<code>static/data/i18n/*.json</code>)</li></ul>',23)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
